{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.wtw_d2p AS WITH formatted_data AS ( SELECT \"Product Title\" AS product_title, TRIM(\"Shopify Product ID\")::VARCHAR AS shopify_product_id, COALESCE( TRY_TO_DATE(\"Request Date\", \'YYYY-MM-DD\'), TRY_TO_DATE(\"Request Date\", \'DD/MM/YY\') ) AS request_date, TRY_TO_DECIMAL(\"Request Count\") AS req_count, SUM(TRY_TO_DECIMAL(\"Request Count\")) OVER ( PARTITION BY TRIM(\"Shopify Product ID\") ORDER BY COALESCE( TRY_TO_DATE(\"Request Date\", \'YYYY-MM-DD\'), TRY_TO_DATE(\"Request Date\", \'DD/MM/YY\') ) ) AS cumulative_wishlist_count, RANK() OVER ( PARTITION BY TRIM(\"Shopify Product ID\") ORDER BY COALESCE( TRY_TO_DATE(\"Request Date\", \'YYYY-MM-DD\'), TRY_TO_DATE(\"Request Date\", \'DD/MM/YY\') ) ASC ) AS cumulative_wishlist_day_count FROM snitch_db.maplemonk.design_wtw_wishlist WHERE \"Request Date\" != \'Request Date\' ), pre_wishlist_rate AS ( SELECT shopify_product_id, product_title, MIN(request_date) AS created_date, SUM(req_count::int) AS total_wishlists_1stweek, (SUM(req_count::int) / COUNT(CUMULATIVE_WISHLIST_DAY_COUNT))::int AS wishlist_rate FROM formatted_data WHERE cumulative_wishlist_day_count <= 7 GROUP BY shopify_product_id, product_title ), sku_media AS ( SELECT id, SUBSTRING(id, CHARINDEX(\'/Product/\', id) + LEN(\'/Product/\'), LEN(id))::VARCHAR AS shopify_product_id, producttype AS category, LEFT(m.value:sku::STRING, LENGTH(m.value:sku::STRING) - POSITION(\'-\' IN REVERSE(m.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(INPUT => t.media) AS f, LATERAL FLATTEN(INPUT => t.variants) AS m QUALIFY ROW_NUMBER() OVER (PARTITION BY id ORDER BY category DESC) = 1 ), image_url AS ( SELECT SUBSTRING(id, CHARINDEX(\'/Product/\', id) + LEN(\'/Product/\'), LEN(id))::VARCHAR AS shopify_product_id, LEFT(variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION(\'-\' IN REVERSE(variant.value:sku::STRING))) AS sku_group, image.value:\"preview\":\"image\":\"url\"::string AS image_url FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(INPUT => PARSE_JSON(t.media)) AS image, LATERAL FLATTEN(INPUT => PARSE_JSON(t.variants)) AS variant WHERE image.value:\"mediaContentType\"::string = \'IMAGE\' QUALIFY ROW_NUMBER() OVER (PARTITION BY t.id ORDER BY image.index) = 1 ), wishlist_rate AS ( SELECT a.*, b.category, c.image_url, b.sku_group FROM pre_wishlist_rate a LEFT JOIN sku_media b ON a.shopify_product_id = b.shopify_product_id LEFT JOIN image_url c ON b.shopify_product_id = c.shopify_product_id ), weekly_benchmarks AS ( SELECT DATE_TRUNC(\'week\', created_date) AS launch_week, category, (PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY wishlist_rate))::int AS weekly_p90_benchmark FROM wishlist_rate WHERE category IS NOT NULL GROUP BY 1,2 ), main_data AS ( SELECT a.*, d.weekly_p90_benchmark, DIV0(a.wishlist_rate, d.weekly_p90_benchmark) AS normalized_score FROM wishlist_rate a LEFT JOIN weekly_benchmarks d ON DATE_TRUNC(\'week\', a.created_date) = d.launch_week AND a.category = d.category QUALIFY ROW_NUMBER() OVER (PARTITION BY shopify_product_id ORDER BY image_url DESC) = 1 ) , moq_pre AS ( SELECT a.sku_group, b.category, a.inventory_on_inward_date FROM snitch_db.maplemonk.original_ros_str_eoq a LEFT JOIN snitch_db.maplemonk.metafields_data b ON a.sku_group = b.sku_group ), moq AS ( SELECT category, DIV0(SUM(inventory_on_inward_date), COUNT(category))::int AS moq FROM moq_pre WHERE category IS NOT NULL GROUP BY 1 ) SELECT a.*, b.moq, CASE WHEN LOWER(a.product_title) LIKE \'%polo%\' AND LOWER(a.product_title) LIKE \'%t-shirt%\' THEN \'T-Shirts\' WHEN LOWER(a.product_title) LIKE \'%polo%\' AND LOWER(a.product_title) LIKE \'%sweatshirt%\' THEN \'Sweatshirts\' WHEN LOWER(a.product_title) LIKE \'%polo%\' AND LOWER(a.product_title) LIKE \'%shirt%\' THEN \'Shirts\' WHEN LOWER(a.product_title) LIKE \'%oversized%\' AND LOWER(a.product_title) LIKE \'%polo%\' THEN \'T-Shirts\' WHEN LOWER(a.product_title) LIKE \'%sweater%\' THEN \'Sweaters\' WHEN LOWER(a.category) = \'pants\' THEN \'Trousers\' WHEN LOWER(a.category) = \'shackets\' THEN \'Overshirts\' WHEN LOWER(a.category) = \'overshirt\' THEN \'Overshirts\' ELSE a.category END AS CATEG, CASE WHEN a.wishlist_rate <= 5 THEN \'no\' WHEN a.normalized_score >= 0.9 THEN \'high\' WHEN a.normalized_score >= 0.7 THEN \'medium\' WHEN a.normalized_score >= 0.55 THEN \'low\' ELSE \'no\' END AS confidence, CASE WHEN a.wishlist_rate > 5 AND a.normalized_score >= 0.9 THEN b.moq * 2 WHEN a.wishlist_rate > 5 AND a.normalized_score >= 0.7 THEN b.moq * 1.5 WHEN a.wishlist_rate > 5 AND a.normalized_score >= 0.55 THEN b.moq ELSE 0 END AS quant_req FROM main_data a LEFT JOIN moq b ON a.category = b.category;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            